import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[] b = new long[(int) m];
        for (int i = 0; i < b.length; i++) b[i] = Long.parseLong(next());

        long[] x = a, y = b;
        if (x.length > y.length) {
            long[] t = x; x = y; y = t;
        }
        int nx = x.length, ny = y.length;
        final long INF = 4000000000000000000L;
        int half = (nx + ny + 1) / 2, lo = 0, hi = nx;
        while (lo <= hi) {
            int i = (lo + hi) / 2, j = half - i;
            long aL = i > 0 ? x[i - 1] : -INF;
            long aR = i < nx ? x[i] : INF;
            long bL = j > 0 ? y[j - 1] : -INF;
            long bR = j < ny ? y[j] : INF;
            if (aL <= bR && bL <= aR) {
                if ((nx + ny) % 2 == 1) System.out.println(2 * Math.max(aL, bL));
                else System.out.println(Math.max(aL, bL) + Math.min(aR, bR));
                break;
            } else if (aL > bR) {
                hi = i - 1;
            } else {
                lo = i + 1;
            }
        }
    }
}
